`
DRESULT disk_write (

	BYTE drv,			/* Physical drive nmuber (0..) */

	const BYTE *buff,	/* Data to be written */

	DWORD sector,		/* Sector address (LBA) */

	BYTE count			/* Number of sectors to write (1..255) */

)

{

	FFSDEBUG("disk_write(sector %d, count %d) on drv [%d]\n", sector, count, drv);

	for(unsigned int s=sector; s<sector+count; s++) {

		FFSDEBUG(" disk_write(sector %d)\n", s);

		int res = FATFileSystem::_ffs[drv]->disk_write((char*)buff, sector); // <- this is wrong, use "s"

		if(res) {

			return RES_PARERR;

		}

		buff += 512;

	}

	return RES_OK;

}
