+uint16_t calculate_crc(void * restrict desc, uint16_t size) {
+    uint8_t offset = sizeof(tag);
+    tag *descTag = desc;
+    uint16_t crc = 0;
+
+    if(size >= 16) {
+        uint16_t calcCrc = udf_crc((uint8_t *)(desc) + offset, size - offset, crc);
+        return calcCrc;
+    } else {
+        return 0;
+    }
+}
