+ */
+int crc(void * restrict desc, uint16_t size) {
+    uint16_t calcCrc = calculate_crc(desc, size);
+    tag *descTag = desc;
+    dbg("Calc CRC: 0x%04x, TagCRC: 0x%04x\n", calcCrc, descTag->descCRC);
+    return le16_to_cpu(descTag->descCRC) != calcCrc;
